query Reports {
  reports {
    code
    group
    groupLabel
    title
    description
    common
    defaultPreset
    filters {
      key
      label
      type
      options {
        value
        label
      }
      default
    }
  }
}

query Report($code: String!, $filters: [ReportFilterInput!], $page: Int, $pageSize: Int) {
  report(code: $code, filters: $filters, page: $page, pageSize: $pageSize) {
    report {
      code
      group
      groupLabel
      title
      description
      common
      defaultPreset
      filters {
        key
        label
        type
        default
      }
    }
    applied {
      key
      value
    }
    errors
    columns {
      key
      label
      type
      link
    }
    rows
    total
    totals
    tiles {
      label
      value
      note
      tone
    }
    note
  }
}

